// Embedded fonts (subsetted, base64 woff2) so the app is self-contained on
// file:// AND so PNG export (rasterized SVG) renders the right font. A <style>
// registers them; export-png.js injects APP.FONT_CSS into the export SVG.
// Instruments use B612 / B612 Mono; placards offer the APP.FONTS choices.
// NOTE: 'Gorton' is non-commercial (see fonts/GORTON-LICENSE.txt) and its
// metrics were tightened (sidebearings only) for even spacing.
window.APP = window.APP || {};
APP.FONT_CSS = "@font-face{font-family:'B612';font-weight:400;font-style:normal;font-display:swap;src:url(data:font/woff2;base64,) format('woff2');}@font-face{font-family:'B612';font-weight:700;font-style:normal;font-display:swap;src:url(data:font/woff2;base64,) format('woff2');}@font-face{font-family:'B612 Mono';font-weight:400;font-style:normal;font-display:swap;src:url(data:font/woff2;base64,) format('woff2');}@font-face{font-family:'Barlow Semi Condensed';font-weight:500;font-style:normal;font-display:swap;src:url(data:font/woff2;base64,) format('woff2');}@font-face{font-family:'League Spartan';font-weight:700;font-style:normal;font-display:swap;src:url(data:font/woff2;base64,) format('woff2');}@font-face{font-family:'Gorton';font-weight:400;font-style:normal;font-display:swap;src:url(data:font/woff2;base64,) format('woff2');}";
APP.FONTS = [
  { id: 'b612',    name: 'B612 (modern)',       family: 'B612' },
  { id: 'barlow',  name: 'Condensed (placard)', family: 'Barlow Semi Condensed' },
  { id: 'spartan', name: 'Spartan (geometric)', family: 'League Spartan' },
  { id: 'gorton',  name: 'Gorton (engraved)',   family: 'Gorton' },
];
(function () {
  var s = document.createElement('style');
  s.id = 'app-fonts';
  s.textContent = APP.FONT_CSS;
  (document.head || document.documentElement).appendChild(s);
})();
